// Geometry of the lekomapa mark (a two-part capsule), the single source for the icon files in public/
// (generated by scripts/icons/generate-icons.mjs) and for any component that draws the mark.
// Shape only: colors come from tokens at the place of use. This module is imported by scripts/**, so it must
// stay free of `cloudflare:*` imports and of reportError.
//
// The mark is drawn with fill-rule="evenodd". All paths must be joined into ONE <path> element: the even-odd
// rule only cuts holes within a single path, so separate elements would lose the hole in the capsule half.

export interface BrandMark {
  viewBox: string;
  paths: readonly string[];
}

export const BRAND_MARK: BrandMark = {
  viewBox: "0 0 24 24",
  paths: [
    "M14.758 15.606L11.293 19.071A4.5 4.5 0 0 1 4.929 12.707L8.394 9.242z",
    "M9.242 8.394L12.707 4.929A4.5 4.5 0 0 1 19.071 11.293L15.606 14.758z",
    "M11.788 8.394L13.98 6.202A2.7 2.7 0 0 1 17.798 10.02L15.606 12.212z",
  ],
};

// The rounded tile behind the mark in the browser tab icon and next to the product name (BrandName.astro).
// Phone icons use a full square with their own padding (scripts/icons/generate-icons.mjs).
export const BRAND_TILE = {
  // Side of the square viewBox, in BRAND_MARK units.
  box: 24,
  // Empty margin on each side, as a fraction of the tile: the mark fills the middle 80%.
  padding: 0.1,
  // Corner radius in viewBox units: slightly rounded, not a circle.
  cornerRadius: 3,
} as const;
